{
  "recommendation": "EcoCard",
  "why": "It has the strongest documented promotional sign-up offer currently available: 2,000 sustainability points, redeemable at $0.01 per point for a statement or checking-account credit, for an effective value of $20.",
  "requirements": {
    "eligible_spending": "$5,000 in eligible purchases",
    "time_limit": "Within the first month after account opening",
    "eligibility": "New customers; account must remain open and in good standing when the bonus is awarded"
  },
  "costs_and_terms": {
    "annual_fee": "$50",
    "purchase_apr": "19.99% on carried balances",
    "foreign_transaction_fee": "1.0%"
  },
  "important_caveat": "Returns, chargebacks, disputed transactions, balance transfers, cash equivalents, and fees do not count toward the spending requirement. The promotion is documented as running from August 1, 2025 through December 15, 2025.",
  "bottom_line": "If you can comfortably spend $5,000 in the first month, the EcoCard is the best documented sign-up bonus I found. I did not find a comparable active personal-card cash-back sign-up bonus in the available offers."
}
